const fs = require('fs');

const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
const board = Array(4).fill(0).map(() => Array(4).fill(0));

let idx = 0;
for (let i = 0; i < 4; i++) {
    for (let j = 0; j < 4; j++) {
        const c = input[idx++];
        if (c === 'x') board[i][j] = 1;
        else if (c === 'o') board[i][j] = -3;
        else board[i][j] = 0;
    }
}

let canWin = false;
for (let i = 0; !canWin && i < 4; i++) {
    for (let j = 0; j < 4; j++) {
        if (board[i][j] >= 0) {
            let sumHor = 0, sumDiaUp = 0, sumDiaDown = 0, sumVer = 0;
            if (j < 2)
                sumHor = board[i][j] + board[i][j+1] + board[i][j+2];
            if (i < 2)
                sumVer = board[i][j] + board[i+1][j] + board[i+2][j];
            if (i < 2 && j < 2)
                sumDiaUp = board[i][j] + board[i+1][j+1] + board[i+2][j+2];
            if (i >= 2 && j < 2)
                sumDiaDown = board[i][j] + board[i-1][j+1] + board[i-2][j+2];

            if (sumHor === 2 || sumDiaUp === 2 || sumDiaDown === 2 || sumVer === 2) {
                canWin = true;
                break;
            }
        }
    }
}

console.log(canWin ? "YES" : "NO");

